// @ts-check
import { randomUUID } from "node:crypto";
import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { execute } from "@dwtechs/antity-pgsql";
import { log } from "@dwtechs/winstan";
import { PUBLIC_ROOT } from "../web/engine.js";

/** Served by the `${WEB_MOUNT}/assets/branding` static mount in app.js. */
export const LOGO_DIR = path.join(PUBLIC_ROOT, "assets", "branding");

/** Only names generated by `saveLogo` are ever read back, deleted or exposed. */
export const LOGO_FILE_RE = /^logo-[0-9a-f-]{36}\.(png|jpg|webp|svg)$/;

/**
 * Stores the image on disk, points the branding row at it (clearing `logoUrl`,
 * the either/or alternative) and drops the previous file. The client-supplied
 * filename is never used.
 *
 * @param {number} id branding row id
 * @param {{ userId: number, nickname: string }} consumer
 * @param {{ buffer: Buffer, ext: string }} logo
 * @returns {Promise<Record<string, unknown>|null>} updated row, or null when the row is missing/archived
 */
export async function saveLogo(id, consumer, logo) {
  const file = `logo-${randomUUID()}.${logo.ext}`;
  await mkdir(LOGO_DIR, { recursive: true });
  await writeFile(path.join(LOGO_DIR, file), logo.buffer, { flag: "wx" });

  try {
    // The CTE reads the pre-update value, so one statement yields both the new row and the old file name.
    const res = await execute(
      `WITH old AS (
         SELECT "logoFile" AS previous FROM branding
         WHERE id = $4 AND archived IS NOT TRUE
       )
       UPDATE branding
       SET "logoFile" = $1, "logoUrl" = '', "updatedAt" = NOW(),
           "updaterId" = $2, "updaterName" = $3
       WHERE id = $4 AND archived IS NOT TRUE
       RETURNING *, (SELECT previous FROM old) AS "previousLogoFile"`,
      [file, consumer.userId, consumer.nickname, id],
      null,
    );
    const row = res.rows?.[0];
    if (!row) {
      await removeLogo(file);
      return null;
    }
    const { previousLogoFile, ...updated } = row;
    if (previousLogoFile && previousLogoFile !== file)
      await removeLogo(previousLogoFile);
    return updated;
  } catch (err) {
    await removeLogo(file);
    throw err;
  }
}

/**
 * Best-effort delete: a leftover file is harmless, a failed request is not.
 * @param {string} file
 * @returns {Promise<void>}
 */
async function removeLogo(file) {
  if (!LOGO_FILE_RE.test(file)) return;
  try {
    await unlink(path.join(LOGO_DIR, file));
  } catch (err) {
    log.warn(`removeLogo ${file} failed: ${err?.message || err}`);
  }
}
